        const listIndentations: number[] = [];
        while (index < normalized.length) {
            const line = normalized[index];
            if (/^\s*(`{3,}|~{3,})/.test(line)) {
                break;
            }
            const indentation = listItemIndentation(line);
            if (indentation !== undefined) {
                listIndentations.push(indentation);
                index++;
                continue;
            }
            if (line.trim() === '' || /^\s+\S/.test(line)) {
                index++;
                continue;
            }
            break;
        }

        const baseIndentation = Math.min(...listIndentations);
        if (baseIndentation > 0) {
            for (let lineIndex = start; lineIndex < index; lineIndex++) {
