const cleanMarkdown = (markdown: string): string => {
    const lines = markdown.split('\n');
    const cleaned: string[] = [];
    let fence: string | undefined;

    for (const line of lines) {
        const fenceMatch = /^\s*(`{3,}|~{3,})/.exec(line);
        if (fence) {
            if (fenceMatch?.[1][0] === fence[0]) {
                cleaned.push(line.trimStart());
                fence = undefined;
            } else {
                // Keep indentation inside code blocks because it carries code structure.
                cleaned.push(line);
            }
            continue;
        }

        if (fenceMatch) {
            cleaned.push(line.trimStart());
            fence = fenceMatch[1];
            continue;
        }

        if (/^\s*#{1,6}(?:\s|$)/.test(line) || /^\s*>/.test(line)) {
            cleaned.push(line.trimStart());
            continue;
        }

        cleaned.push(line);
    }

    return normalizeListIndentation(cleaned).join('\n');
};

export const fixNestedLists = (dom: Document): Document => {
    const lists = [...dom.querySelectorAll('ul, ol')].reverse();

    lists.forEach((list) => {
        const parentList = list.parentElement;
        if (!parentList || !['ul', 'ol'].includes(parentList.tagName.toLowerCase())) {
            return;
        }

        const previousItem = list.previousElementSibling;
        const containingItem = previousItem?.tagName.toLowerCase() === 'li' ? previousItem : undefined;
        if (containingItem) {
            containingItem.appendChild(list);
            return;
        }

        const listItem = dom.createElement('li');
        parentList.insertBefore(listItem, list);
        listItem.appendChild(list);
    });

    return dom;
};

