        const stored: StoredUrl = { messageID, url: href };
        savePresentationAttributes(link, stored);
        LinksURLs.set(key, stored);
        link.setAttribute('href', key);
    });

    /**
     * Images can have a remote `src`, a proxy `src` with a `proton-src`, or an
     * embedded `src`. Preserve the original attributes so restoration can put
     * the right source and presentation back after Markdown conversion.
