    const images = dom.querySelectorAll('img[src]');
    const protonSrcImages = dom.querySelectorAll('img[proton-src]');

    images.forEach((image) => {
        const src = image.getAttribute('src');
        const protonSrc = image.getAttribute('proton-src');
        if (!src) {
            return;
        }

        const key = makePlaceholder();
        const stored: StoredUrl = {
            messageID,
            url: src,
            'proton-src': protonSrc || undefined,
            id: image.getAttribute('id') || undefined,
            'data-embedded-img': image.getAttribute('data-embedded-img') || undefined,
        };
        savePresentationAttributes(image, stored);
        ImageURLs.set(key, stored);
        image.setAttribute('src', key);
    });

    protonSrcImages.forEach((image) => {
        if (image.hasAttribute('src')) {
            return;
        }

        const protonSrc = image.getAttribute('proton-src');
        if (!protonSrc) {
            return;
        }

        const key = makePlaceholder();
        const encodedImageUrl = encodeImageUri(protonSrc);
        const proxyImage = forgeImageURL({
            apiUrl: API_URL,
            url: encodedImageUrl,
            uid,
            origin: window.location.origin,
        });
        const stored: StoredUrl = {
            messageID,
            url: proxyImage,
            'proton-src': protonSrc,
            id: image.getAttribute('id') || undefined,
            'data-embedded-img': image.getAttribute('data-embedded-img') || undefined,
        };
        savePresentationAttributes(image, stored);
        ImageURLs.set(key, stored);
        image.setAttribute('src', key);
    });

    return dom;
};

const restoreOrRemoveElement = (
    element: Element,
    key: string | null,
    urls: Map<string, StoredUrl>,
    messageID: string | undefined,
    urlAttribute: string
) => {
    const stored = key ? urls.get(key) : undefined;
    if (!stored || (messageID !== undefined && stored.messageID !== messageID)) {
        if (element.tagName.toLowerCase() === 'a') {
            // Drop the link but keep its visible text and any inline formatting.
            element.replaceWith(...Array.from(element.childNodes));
        } else {
            element.remove();
        }
        return;
    }

    element.setAttribute(urlAttribute, stored.url);
    restoreAttribute(element, 'class', stored.className);
    restoreAttribute(element, 'style', stored.style);

    if (element.tagName.toLowerCase() === 'img') {
        restoreAttribute(element, 'proton-src', stored['proton-src']);
        restoreAttribute(element, 'data-embedded-img', stored['data-embedded-img']);
        restoreAttribute(element, 'id', stored.id);
    }
};

