// are unwrapped so their text remains visible; images are removed.
export const restoreURLs = (dom: Document, messageID?: string): Document => {
    dom.querySelectorAll('a').forEach((link) => {
        restoreOrRemoveElement(link, link.getAttribute('href'), LinksURLs, messageID, 'href');
    });

    dom.querySelectorAll('img').forEach((image) => {
        restoreOrRemoveElement(image, image.getAttribute('src'), ImageURLs, messageID, 'src');
    });

    return dom;
};
